import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'

export async function POST(request: NextRequest) {
  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const { candidateIds, sessionId } = body as { candidateIds?: unknown; sessionId?: unknown }

  if (
    !Array.isArray(candidateIds) ||
    candidateIds.length === 0 ||
    typeof sessionId !== 'string' ||
    !sessionId
  ) {
    return NextResponse.json(
      { error: 'candidateIds (non-empty array) and sessionId (string) are required' },
      { status: 400 }
    )
  }

  const ids = candidateIds as string[]

  const client = await db.connect()
  try {
    await client.query('BEGIN')

    // Update session, status, and active flag on each candidate
    await client.query(
      `UPDATE candidates
         SET session_id = $1,
             status     = 'APPROVED',
             is_active  = true,
             updated_at = NOW()
       WHERE id = ANY($2::text[])`,
      [sessionId, ids]
    )

    // Copy each candidate's existing subjects into the new session.
    // Uses ON CONFLICT DO NOTHING so re-running is safe.
    for (const candidateId of ids) {
      await client.query(
        `INSERT INTO subject_combinations
               (id, subject_id, candidate_id, session_id, created_at, updated_at)
         SELECT gen_random_uuid(), subject_id, $1, $2, NOW(), NOW()
           FROM (
             SELECT DISTINCT subject_id
               FROM subject_combinations
              WHERE candidate_id = $1
           ) AS src
         ON CONFLICT (candidate_id, subject_id, session_id) DO NOTHING`,
        [candidateId, sessionId]
      )
    }

    await client.query('COMMIT')
  } catch (err) {
    await client.query('ROLLBACK')
    console.error('[reassign] db error:', err)
    return NextResponse.json(
      { error: err instanceof Error ? err.message : 'Database error during reassignment' },
      { status: 500 }
    )
  } finally {
    client.release()
  }

  return NextResponse.json({ success: true, updated: ids.length })
}
